INSERT INTO `pages` VALUES (1,'2025-09-17 16:24:39.748','2025-12-23 06:19:31.376','关于我','# 关于我 👋\n\n## 个人简介\n欢迎来到我的个人博客！我是一名充满热情的开发者，专注于现代Web技术和软件工程。\n\n## 技术栈 💻\n- **后端开发**: Go, Python, Node.js\n- **前端技术**: HTML5, CSS3, JavaScript, React, Vue.js\n- **数据库**: MySQL, PostgreSQL, SQLite, Redis\n- **云服务**: AWS, Docker, Kubernetes\n- **版本控制**: Git, GitHub\n\n## 兴趣爱好 🎯\n- 💻 编程与软件开发\n- 📚 技术文章阅读与写作\n- 🌱 学习新技术和框架\n- 🎮 偶尔玩玩游戏放松\n- 🏃‍♂️ 户外运动与健身\n\n## 博客初衷 ✨\n这个博客是我记录学习心得、分享技术经验和表达个人想法的地方。希望通过分享：\n\n- 帮助其他开发者解决问题\n- 记录自己的成长历程\n- 建立技术交流的桥梁\n- 保持持续学习的习惯\n\n## 联系方式 📫\n如果你对我的文章有任何疑问，或者想要技术交流，欢迎通过以下方式联系我：\n\n- **GitHub**: [github.com/xiuivfbc](https://github.com/xiuivfbc)\n- **Email**: 可以通过GitHub获取\n- **技术交流**: 欢迎在博客文章下留言讨论\n\n## 最近在做什么 🚀\n- 🔥 持续优化这个博客系统\n- 📖 深入学习Go语言生态\n- 🌐 探索现代前端框架\n- 📝 准备更多高质量的技术文章\n\n---\n\n*感谢你的访问，希望我的博客能给你带来价值！*\n\n> "代码改变世界，学习永不止步" 💪',25,1);

