INSERT INTO `posts` VALUES (2,'2025-09-17 16:26:38.145','2025-12-21 16:28:37.534','虫大','[虫大](https://cqu.edu.cn)',13,1,NULL),(3,'2025-09-19 09:30:15.095','2025-09-23 14:23:33.243','史诗级领地设计师','[欣赏少爷的盛世美颜吧](https://manwa.me/book/19703)\r\n',12,1,NULL),(4,'2025-09-22 15:45:58.536','2025-12-20 13:38:47.878','知乎','[传送门](https://www.zhihu.com/)',12,1,NULL),(5,'2025-09-22 15:46:33.246','2025-12-20 13:38:44.745','小红书','[传送门](https://www.xiaohongshu.com/explore)',10,1,NULL),(7,'2025-09-23 11:41:58.473','2025-12-21 17:13:10.740','GitHub','[传送门](https://github.com)\r\n\r\n全球最大的代码托管平台，开发者的天堂。无论是开源项目还是私有仓库，GitHub都提供了完善的版本控制和协作功能。',31,1,NULL),(8,'2025-09-22 11:41:58.473','2025-10-20 23:22:29.963','Stack Overflow','[传送门](https://stackoverflow.com)\n\n程序员问答社区，解决编程难题的最佳去处。几乎任何编程问题都能在这里找到答案。',16,1,NULL),(9,'2025-09-21 11:41:58.473','2025-10-13 21:37:52.487','MDN Web Docs','[传送门](https://developer.mozilla.org)\r\n\r\nWeb开发者的权威文档，提供HTML、CSS、JavaScript等前端技术的详细文档和教程。\r\n\r\nlala',21,1,NULL),(10,'2025-09-20 11:41:58.473','2025-10-09 14:14:56.325','阮一峰的网络日志','[传送门](http://www.ruanyifeng.com/blog/)\n\n技术大牛阮一峰的个人博客，涵盖前端技术、计算机科学等多个领域的深度文章。',27,1,NULL),(11,'2025-09-19 11:41:58.473','2025-10-13 21:38:00.541','掘金','[传送门](https://juejin.cn)\r\n\r\n中文技术社区，汇聚了众多优秀的技术文章和开发者分享。前端、后端、移动开发应有尽有。\r\n\r\nlala',31,1,NULL),(12,'2025-09-18 11:41:58.473','2025-10-13 21:38:04.245','Medium-lala','[传送门](https://medium.com)\r\n\r\n高质量的技术博客平台，许多知名技术专家和公司都在这里分享深度技术见解。',36,1,NULL),(13,'2025-09-17 11:41:58.473','2025-09-17 11:41:58.473','Dev.to','[传送门](https://dev.to)\n\n开发者社区，提供友好的环境让开发者分享经验、学习新技术。界面简洁，内容质量很高。',40,1,NULL),(14,'2025-09-16 11:41:58.473','2025-09-16 11:41:58.473','Hacker News','[传送门](https://news.ycombinator.com)\n\n硅谷创业孵化器Y Combinator运营的新闻聚合网站，技术和创业资讯的优质来源。',45,1,NULL),(15,'2025-09-15 11:41:58.473','2025-09-23 14:23:30.787','Redis','[传送门](https://redis.io)\n\n高性能的内存数据库，支持多种数据结构。在缓存、消息队列、实时数据处理等场景中广泛应用。',51,1,NULL),(16,'2025-09-14 11:41:58.473','2025-12-21 16:28:29.713','Docker','[传送门](https://www.docker.com)\n\n容器化技术的领导者，让应用部署变得简单高效。DevOps和云原生开发的必备工具。',58,1,NULL);

